class Solution {
    public long findKthSmallest(int[] coins, int k) {
        long low = 1;
        long high = (long) 1e18; // large enough upper bound

        while (low < high) {
            long mid = low + (high - low) / 2;
            if (count(mid, coins) >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    // Count how many amounts <= limit can be made
    private long count(long limit, int[] coins) {
        long total = 0;
        int n = coins.length;

        // Inclusion-exclusion over subsets of coins
        for (int mask = 1; mask < (1 << n); mask++) {
            long lcm = 1;
            int bits = 0;
            boolean tooLarge = false;

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    bits++;
                    lcm = lcm(lcm, coins[i]);
                    if (lcm > limit) {
                        tooLarge = true;
                        break;
                    }
                }
            }

            if (tooLarge) continue;

            if (bits % 2 == 1) {
                total += limit / lcm;
            } else {
                total -= limit / lcm;
            }
        }
        return total;
    }

    private long gcd(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    private long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }
}

