class Solution {
    public long minEnd(int n, int x) {
        // We need to construct n strictly increasing positive integers
        // whose bitwise AND equals x.
        // To minimize the last element, we start with x as the first number.
        // Then we need to fill the remaining n - 1 numbers by using bits
        // that are not set in x, because any bit set to 0 in x must remain 0
        // in all numbers to keep the AND result equal to x.
        // The smallest possible sequence is obtained by taking the binary
        // representation of (n - 1) and inserting its bits into the zero bit
        // positions of x (from least significant to most significant).

        long result = x;
        long remaining = n - 1;
        int bitPosition = 0;

        // We iterate over the bits of x from LSB to MSB.
        // Whenever we find a 0 bit in x, we can place the next bit of (n-1) there.
        // This ensures the numbers stay as small as possible while preserving AND = x.
        while (remaining > 0) {
            // Check if the current bit of x is 0
            if ((x & (1L << bitPosition)) == 0) {
                // Place the LSB of remaining into this zero bit position
                long bitToPlace = remaining & 1L;
                result |= (bitToPlace << bitPosition);
                remaining >>= 1;
            }
            bitPosition++;
        }

        return result;
    }
}

class Solution {
    public int maximumStrongPairXor(int[] nums) {
        int maxXor = 0;
        int n = nums.length;

        // Sort the array to use a two-pointer approach for finding strong pairs
        Arrays.sort(nums);

        // For each possible left endpoint of the strong pair
        for (int i = 0; i < n; i++) {
            int left = i;
            int right = i;

            // Expand the right pointer while the strong pair condition holds
            while (right < n && nums[right] - nums[left] <= nums[left]) {
                maxXor = Math.max(maxXor, nums[left] ^ nums[right]);
                right++;
            }
        }

        return maxXor;
    }
}

