class Solution {
    public int[] minimumCost(int n, int[][] edges, int[][] query) {
        int[] p = new int[n];
        int[] a = new int[n];
        for (int i = 0; i < n; i++) { p[i] = i; a[i] = 0x7fffffff; }
        for (int[] e : edges) {
            int x = e[0], y = e[1], w = e[2];
            int rx = f(p, x), ry = f(p, y);
            if (rx != ry) {
                p[rx] = ry;
                a[ry] = a[rx] & a[ry];
            }
            a[ry] &= w;
        }
        int[] r = new int[query.length];
        for (int i = 0; i < query.length; i++) {
            int s = query[i][0], t = query[i][1];
            int rs = f(p, s), rt = f(p, t);
            r[i] = (rs == rt) ? a[rt] : -1;
        }
        return r;
    }
    private int f(int[] p, int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
}

