class Solution {
    public int minimumSubarrayLength(int[] nums, int k) {
        int[] c = new int[32];
        int l = 0, r = 0, n = nums.length, m = Integer.MAX_VALUE, o = 0;
        while (r < n) {
            o |= nums[r];
            for (int b = 0; b < 31; b++) if ((nums[r] & (1 << b)) != 0) c[b]++;
            while (l <= r && o >= k) {
                m = Math.min(m, r - l + 1);
                for (int b = 0; b < 31; b++) if ((nums[l] & (1 << b)) != 0 && --c[b] == 0) o &= ~(1 << b);
                l++;
            }
            r++;
        }
        return m == Integer.MAX_VALUE ? -1 : m;
    }
}

class Solution {
