class Solution {
    public boolean canSortArray(int[] nums) {
        int[] b = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            while (x != 0) {
                b[i] += x & 1;
                x >>= 1;
            }
        }
        int i = 0;
        while (i < nums.length) {
            int j = i;
            int mn = nums[i], mx = nums[i];
            while (j < nums.length && b[j] == b[i]) {
                mn = Math.min(mn, nums[j]);
                mx = Math.max(mx, nums[j]);
                j++;
            }
            for (int k = i; k < j; k++) {
                if (nums[k] < mn || nums[k] > mx) return false;
            }
            if (i > 0 && mn < nums[i - 1]) return false;
            i = j;
        }
        return true;
    }
}

class Solution {
    public int minimumValueSum(int[] nums, int[] andValues) {
        int n = nums.length;
        int m = andValues.length;
        final int INF = Integer.MAX_VALUE / 2;

        // dp[i][j] = minimum sum of values for first i elements of nums
        // divided into j subarrays satisfying the AND conditions.
        int[][] dp = new int[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = INF;
            }
        }
        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                int currentAnd = nums[i - 1];
                // Try all possible starts of the last subarray ending at i-1
                for (int k = i - 1; k >= 0; k--) {
                    if (k < i - 1) {
                        currentAnd &= nums[k];
                    }
                    if (currentAnd == andValues[j - 1]) {
                        if (dp[k][j - 1] != INF) {
                            dp[i][j] = Math.min(dp[i][j], dp[k][j - 1] + nums[i - 1]);
                        }
                    }
                    // Early break: once AND becomes smaller than target,
                    // further extending left will only keep it same or smaller.
                    if (currentAnd < andValues[j - 1]) {
                        break;
                    }
                }
            }
        }

        return dp[n][m] == INF ? -1 : dp[n][m];
    }
}

