class Solution {
    public int minimumSubarrayLength(int[] nums, int k) {
        int n = nums.length;
        int minLength = Integer.MAX_VALUE;

        // We will maintain OR values for subarrays ending at the current position.
        // Each entry in the list is an array of two elements: [OR value, leftmost start index].
        List<int[]> ors = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            // Append the current element as a new subarray of length 1.
            ors.add(new int[]{0, i});

            // Update all existing OR values with the current element.
            int writeIndex = 0;
            for (int j = 0; j < ors.size(); j++) {
                int[] current = ors.get(j);
                current[0] |= nums[i];

                // Merge consecutive entries with the same OR value to keep the list small.
                if (writeIndex > 0 && ors.get(writeIndex - 1)[0] == current[0]) {
                    ors.get(writeIndex - 1)[1] = current[1];
                } else {
                    ors.set(writeIndex, current);
                    writeIndex++;
                }
            }

            // Remove the extra entries beyond writeIndex.
            ors.subList(writeIndex, ors.size()).clear();

            // Check if any subarray ending at i meets the condition.
            for (int[] entry : ors) {
                if (entry[0] >= k) {
                    minLength = Math.min(minLength, i - entry[1] + 1);
                }
            }
        }

        return minLength == Integer.MAX_VALUE ? -1 : minLength;
    }
}

