class Solution {
    public int[] minimumCost(int n, int[][] edges, int[][] query) {
        int[] parent = new int[n];
        int[] rank = new int[n];
        int[] compAnd = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
            compAnd[i] = Integer.MAX_VALUE;
        }

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int w = edge[2];
            union(u, v, parent, rank);
        }

        for (int[] edge : edges) {
            int u = edge[0];
            int w = edge[2];
            int root = find(u, parent);
            compAnd[root] &= w;
        }

        int[] answer = new int[query.length];
        for (int i = 0; i < query.length; i++) {
            int s = query[i][0];
            int t = query[i][1];
            int rootS = find(s, parent);
            int rootT = find(t, parent);
            if (rootS != rootT) {
                answer[i] = -1;
            } else {
                answer[i] = compAnd[rootS];
            }
        }

        return answer;
    }

    private int find(int x, int[] parent) {
        if (parent[x] != x) {
            parent[x] = find(parent[x], parent);
        }
        return parent[x];
    }

    private void union(int x, int y, int[] parent, int[] rank) {
        int rootX = find(x, parent);
        int rootY = find(y, parent);
        if (rootX == rootY) return;
        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }
}

