class Solution {
    public long findMaximumNumber(long k, int x) {
        long lo = 1, hi = 1;
        while (true) {
            long v = hi;
            long c = 0;
            for (int bit = x - 1; bit < 63; bit += x) {
                long period = 1L << (bit + 1);
                long full = (v + 1) / period;
                long rem = (v + 1) % period;
                c += full * (1L << bit);
                if (rem > (1L << bit)) c += rem - (1L << bit);
            }
            if (c > k) break;
            hi <<= 1;
        }
        while (lo < hi) {
            long mid = (lo + hi + 1) >>> 1;
            long c = 0;
            for (int bit = x - 1; bit < 63; bit += x) {
                long period = 1L << (bit + 1);
                long full = (mid + 1) / period;
                long rem = (mid + 1) % period;
                c += full * (1L << bit);
                if (rem > (1L << bit)) c += rem - (1L << bit);
            }
            if (c <= k) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
}

