    public int[] minimumCost(int n, int[][] edges, int[][] query) {
        // Union-Find data structure to track connected components
        int[] parent = new int[n];
        int[] rank = new int[n];
        // componentAnd[i] stores the bitwise AND of all edge weights in component i
        int[] componentAnd = new int[n];

        // Initialize Union-Find
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 1;
            componentAnd[i] = Integer.MAX_VALUE; // all bits set initially
        }

        // Find with path compression
        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                if (parent[x] != x) {
                    parent[x] = applyAsInt(parent[x]);
                }
                return parent[x];
            }
        };

        // Union two components
        java.util.function.BiConsumer<Integer, Integer> union = (a, b) -> {
            int rootA = find.applyAsInt(a);
            int rootB = find.applyAsInt(b);
            if (rootA == rootB) return;

            if (rank[rootA] < rank[rootB]) {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }
            parent[rootB] = rootA;
            if (rank[rootA] == rank[rootB]) {
                rank[rootA]++;
            }
            componentAnd[rootA] &= componentAnd[rootB];
        };

        // Process all edges
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int w = edge[2];

            int rootU = find.applyAsInt(u);
            int rootV = find.applyAsInt(v);

            if (rootU == rootV) {
                // Already in same component, just update AND
                componentAnd[rootU] &= w;
            } else {
                // Merge components and update AND
                union.accept(u, v);
                int newRoot = find.applyAsInt(u);
                componentAnd[newRoot] &= w;
            }
        }

        // Answer queries
        int[] answer = new int[query.length];
        for (int i = 0; i < query.length; i++) {
            int s = query[i][0];
            int t = query[i][1];

            int rootS = find.applyAsInt(s);
            int rootT = find.applyAsInt(t);

            if (rootS != rootT) {
                answer[i] = -1;
            } else {
                answer[i] = componentAnd[rootS];
            }
        }

        return answer;
    }
}

