class Solution {
    public long findMaximumNumber(long k, int x) {
        long low = 1, high = 1;

        // Find an upper bound for binary search
        while (accumulatedPrice(high, x) <= k) {
            high <<= 1;
        }

        // Binary search for the maximum number with accumulated price <= k
        while (low < high) {
            long mid = low + (high - low + 1) / 2;
            if (accumulatedPrice(mid, x) <= k) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }

        return low;
    }

    // Calculate the total price of numbers from 1 to n
    private long accumulatedPrice(long n, int x) {
        long total = 0;
        // Check each bit position that is a multiple of x
        for (int bit = x; bit <= 60; bit += x) {
            total += countSetBitsAtPosition(n, bit);
        }
        return total;
    }

    // Count how many numbers from 1 to n have the bit at the given position set
    private long countSetBitsAtPosition(long n, int bitPosition) {
        long bitValue = 1L << (bitPosition - 1);
        long cycleLength = bitValue << 1;

        long fullCycles = n / cycleLength;
        long count = fullCycles * bitValue;

        long remainder = n % cycleLength;
        if (remainder >= bitValue) {
            count += remainder - bitValue + 1;
        }

        return count;
    }
}

class Solution {
    public int maximumStrongPairXor(int[] nums) {
        java.util.Arrays.sort(nums);
        int max = 0, n = nums.length;
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            int limit = x * 2;
            int j = i;
            while (j < n && nums[j] <= limit) {
                int y = nums[j];
                int xor = x ^ y;
                if (xor > max) max = xor;
                j++;
            }
        }
        return max;
    }
}

