class Solution {
    public long findKthSmallest(int[] coins, int k) {
        long lo = 1, hi = (long) 1e18;
        while (lo < hi) {
            long mid = (lo + hi) >>> 1;
            if (count(coins, mid) >= k) hi = mid; else lo = mid + 1;
        }
        return lo;
    }

    private long count(int[] c, long m) {
        long s = 0;
        int n = c.length;
        for (int mask = 1; mask < (1 << n); mask++) {
            long l = 1;
            int bits = 0;
            for (int i = 0; i < n; i++) if ((mask & (1 << i)) != 0) {
                bits++;
                l = lcm(l, c[i]);
                if (l > m) break;
            }
            if (l <= m) {
                long add = m / l;
                if ((bits & 1) == 1) s += add; else s -= add;
            }
        }
        return s;
    }

    private long gcd(long a, long b) {
        while (b != 0) { long t = a % b; a = b; b = t; }
        return a;
    }

    private long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }
}

class Solution {
    public long findMaximumNumber(long k, int x) {
        long low = 1, high = 1;
        // Find an upper bound
        while (accumulatedPrice(high, x) <= k) {
