        }

        while (low < high) {
            long mid = low + (high - low + 1) / 2;
            if (accumulatedPrice(mid, x) <= k) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private long accumulatedPrice(long n, int x) {
        long total = 0;
        // For each bit position that is a multiple of x (1-indexed from LSB)
        for (int bit = x; bit <= 60; bit += x) {
            total += countSetBitsAtPosition(n, bit);
        }
        return total;
    }

    private long countSetBitsAtPosition(long n, int pos) {
        // pos is 1-indexed from LSB
        long period = 1L << pos;
        long halfPeriod = period >> 1;

        long fullCycles = n / period;
        long remainder = n % period;

        long count = fullCycles * halfPeriod;
        if (remainder >= halfPeriod) {
            count += remainder - halfPeriod + 1;
        }
        return count;
    }
}

