class Solution {
    public int minimumValueSum(int[] nums, int[] andValues) {
        int n = nums.length, m = andValues.length;
        int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[m + 1][n + 1];
        for (int i = 0; i <= m; i++) java.util.Arrays.fill(dp[i], INF);
        dp[0][0] = 0;
        for (int i = 0; i < m; i++) {
            int target = andValues[i];
            for (int j = i; j < n; j++) {
                if (dp[i][j] == INF) continue;
                int cur = nums[j];
                for (int k = j; k < n; k++) {
                    cur &= nums[k];
                    if (cur == target) {
                        if (dp[i + 1][k + 1] > dp[i][j] + nums[k]) {
                            dp[i + 1][k + 1] = dp[i][j] + nums[k];
                        }
                    }
                    if (cur < target) break;
                }
            }
        }
        return dp[m][n] >= INF ? -1 : dp[m][n];
    }
}

