class Solution {
    public boolean canSortArray(int[] nums) {
        int n = nums.length;
        int[] sorted = nums.clone();
        java.util.Arrays.sort(sorted);

        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && Integer.bitCount(nums[j]) == Integer.bitCount(nums[i])) {
                j++;
            }
            // segment [i, j-1] has same set bit count
            int[] segment = java.util.Arrays.copyOfRange(nums, i, j);
            java.util.Arrays.sort(segment);
            for (int k = i; k < j; k++) {
                if (segment[k - i] != sorted[k]) {
                    return false;
                }
            }
            i = j;
        }
        return true;
    }
}

