class Solution {
    public boolean canSortArray(int[] nums) {
        int n = nums.length;

        // We'll process the array in segments where all numbers have the same bit count.
        int i = 0;
        int prevSegmentMax = 0;

        while (i < n) {
            int bitCount = Integer.bitCount(nums[i]);
            int segmentMin = nums[i];
            int segmentMax = nums[i];

            // Find the full segment of numbers with the same bit count.
            while (i < n && Integer.bitCount(nums[i]) == bitCount) {
                segmentMin = Math.min(segmentMin, nums[i]);
                segmentMax = Math.max(segmentMax, nums[i]);
                i++;
            }

            // If the smallest number in this segment is smaller than the largest
            // number in the previous segment, sorting is impossible.
            if (segmentMin < prevSegmentMax) {
                return false;
            }

            prevSegmentMax = segmentMax;
        }

        return true;
    }
}

