class Solution {
    public int minimumValueSum(int[] nums, int[] andValues) {
        int n = nums.length;
        int m = andValues.length;
        final int INF = Integer.MAX_VALUE / 2;

        // dp[i][j] = min sum for first i elements divided into j subarrays
        int[][] dp = new int[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = INF;
            }
        }
        dp[0][0] = 0;

        for (int j = 1; j <= m; j++) {
            int target = andValues[j - 1];
            // For each possible start position of the j-th subarray
            for (int i = j; i <= n; i++) {
                int and = nums[i - 1];
                // Try all possible starts for the subarray ending at i
                for (int k = i; k >= j; k--) {
                    if (k < i) {
                        and &= nums[k - 1];
                    }
                    if (and == target) {
                        if (dp[k - 1][j - 1] != INF) {
                            dp[i][j] = Math.min(dp[i][j], dp[k - 1][j - 1] + nums[i - 1]);
                        }
                    }
                    // Early break if AND becomes smaller than target (can't increase back)
                    if (and < target) {
                        break;
                    }
                }
            }
        }

        return dp[n][m] >= INF ? -1 : dp[n][m];
    }
}

import java.util.regex.Pattern;

final class Solution {
    public boolean solution(String text) {
        String pattern = "^[A-Za-z][A-Za-z0-9_]{3,14}$";
        return Pattern.compile(pattern).matcher(text).find();
    }
}

